"""Checkpoint retained layout, presentation and initial producer review."""
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,subprocess
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2];NAME='rootstock_layout_review_receipt.json'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
load=lambda n:json.loads((HERE/n).read_text(encoding='utf-8-sig'))
def git(*a):return subprocess.check_output(['git',*a],cwd=ROOT,text=True).strip()
def save(n,v):(HERE/n).write_text(json.dumps(v,indent=2)+'\n',encoding='utf-8')
assert not (HERE/NAME).exists()
old=load('rootstock_host_review_receipt.json');head=git('rev-parse','HEAD');assert head==old['basis_commit']
guards={**old['preserved_production_and_test_hashes'],**old['source_sha256']};assert len(guards)==1590
assert all(sha(ROOT/n)==h for n,h in guards.items()) and all(sha(HERE/n)==h for n,h in old['evidence_sha256'].items())
doc=ROOT/old['document']['path'];prefix=doc.read_bytes();assert sha(doc)==old['document']['sha256']
assert all(sha(ROOT/n)==h for n,h in old['shared_working_file_sha256'].items() if n!=old['document']['path'])
index=Path(git('rev-parse','--git-path','index'));index=index if index.is_absolute() else ROOT/index;index_hash=sha(index)
inv,cov=load('source_inventory.json'),load('read_coverage.json');assert inv['commit']==head and load('pending_read.json')==[]
whole=sorted(n for n,v in inv['files'].items() if n.startswith('crates/cambium/cambium-rootstock/') and n not in guards and cov.get(n,{}).get('sha256')==v['sha256'] and cov[n]['through']==v['chars'])
assert len(whole)==18 and sum(inv['files'][n]['chars'] for n in whole)==194499
assert all(sha(ROOT/n)==inv['files'][n]['sha256'] for n in whole)
stats=json.loads(subprocess.check_output(['python',str(HERE/'read_coverage.py'),'status'],cwd=ROOT))
assert stats['complete_files']==2079 and stats['read_chars']==25038070 and not stats['changed_since_inventory'] and not stats['pending_chunks']
caret=load('rootstock_caret_probe_receipt.json');typed=load('rootstock_embedding_info_v2_probe_receipt.json');failed=load('rootstock_embedding_info_probe_receipt.json')
assert caret['build_exits']==[0,0,0] and caret['run_exit']==0 and caret['checks']==8
assert typed['build_exits']==[0,0,1] and typed['run_exit'] is None and typed['checks']==0
errors=(HERE/'rootstock_embedding_info_v2_probe_compile_2.log').read_text();assert errors.count('error[E')==1 and 'E0063' in errors and 'missing field `purpose`' in errors
assert failed['build_exits']==[0,0,1] and failed['run_exit'] is None and 'E0463' in (HERE/'rootstock_embedding_info_probe_compile_2.log').read_text()
for probe in [caret,typed,failed]:
 assert probe['generated_output_removed'] and all(not Path(o['path']).exists() for o in probe['removed_outputs'])
 assert all(sha(ROOT/n)==h for n,h in probe['source_sha256'].items()) and all(sha(Path(v['path']))==v['sha256'] for v in probe['libraries'].values())
embedding=(ROOT/'crates/cambium/cambium-rootstock/src/embedding.rs').read_text()
start=embedding.index('        let info = ProducerFrameInfo {');end=embedding.index('\n        };',start)+len('\n        };')
expression=embedding[start:end]
assert expression in (HERE/'rootstock_embedding_info_v2_probe.rs').read_text() and 'purpose' not in expression
notes,authority=load('review_notes.json'),load('authority_map.json');assert notes['findings'][-1]['id']=='Q306' and authority['entries'][-1]['id']=='A781'
findings=[
 {'id':'Q307','title':'Host visual-caret correction overwrites correct toolkit selection with a separate scalar editor',
  'source':'crates/cambium/cambium-rootstock/src/owned_layout.rs:608,1357,1364; crates/cambium/cambium-rootstock/src/input.rs:420',
  'status':'verified original current toolkit and Rootstock over retained exact suppliers',
  'evidence':'OwnedLayout::selection_visual_move does not consult shaped line/bidi geometry: it concatenates DOM text, walks Unicode scalar boundaries, treats LineStart/LineEnd as buffer ends and collapses from the selection focus instead of the correct selection edge. Host::move_focused_text_visual overwrites the logical result with this answer whenever layout exists and default is unprevented. Eight original-current checks compare otherwise-identical Hosts with/without layout: multiline Home from byte 4 in ab\\ncd correctly goes to 3 without layout but 0 with it; End from byte 1 correctly goes to 2 but is overwritten to 5; Left on selection 1..3 in abcd correctly collapses to 1 but becomes 2; Right from the start of a-combining-acute+b correctly advances to byte 3 but the layout correction snaps it back to byte 0. These are actual Host/model observations, not native key injection or visual/bidi acceptance.',
  'diagnostics':['rootstock_caret_probe_receipt.json'],
  'repair_triage':{'disposition':'documented; production unchanged under active read-only audit goal','reason':'A narrow repair can stop replacing valid toolkit movement with this nonvisual fallback. A real visual move must delegate to shaped layout/selection authority while preserving grapheme, selection-edge, multiline and modifier semantics; document broad bidi/soft-wrap restoration rather than inventing another editor.'}},
 {'id':'Q308','title':'Optional embedding frame initialization omits the current required producer purpose',
  'source':'crates/cambium/cambium-rootstock/src/embedding.rs:277; crates/cambium/cambium-rootstock/src/producer.rs:85',
  'status':'compiler-confirmed exact current initializer against fresh current public type; full optional feature graph not built',
  'evidence':'ProducerFrameInfo now requires purpose to distinguish Presentation from Export. embedding::View::frame still initializes logical/physical size, scale, needs_frame, timestamp and appearance without purpose. The exact initializer text extracted from current embedding.rs, in a minimal receiver fixture, compiles against freshly built original current Rootstock and produces only E0063 missing field purpose. The no-optional-feature original Rootstock builds first, demonstrating why those passing builds miss the inactive module. The first extraction harness could not resolve the fresh Cambium dependency (E0463); it is retained as a failed diagnostic and a distinct v2 explicitly loads that dependency. No whole embedding/egui/Iced feature build, GPU or runtime claim is made.',
  'diagnostics':['rootstock_embedding_info_v2_probe_receipt.json'],
  'repair_triage':{'disposition':'documented; production unchanged under active read-only audit goal','reason':'Supply the intended producer purpose at the actual embedding frame boundary and verify its presentation/export behavior. Include the optional embedding feature in its own gate; a default host build is not coverage for inactive modules.'}}
]
for f in findings:f['verification']=NAME
notes['findings'].extend(findings)
rows=[
 ('Multi-window receipts are narrower than portable view custody','Multi-host tests preserve a manually appended DOM node and shared leaf, not a moved PortableKeyed component across projection contexts.', ['multi_host_tests.rs'], 'The test creates its own tile beside the runner view then calls ScriptedDom::move_before directly. It establishes layout/mutation routing and painter retention for that raw node, not forest nursery adoption Q301. Other source tests cover subtree-specific layout/a11y, shared state refresh, native form notifications, sheets and qualified secondary capture. These source tests were read, not broadly rerun.'),
 ('Two editors compete at the host caret boundary','Toolkit TextInput owns logical editing, but Rootstock applies its independent scalar text walk as a supposedly visual correction.', ['owned_layout.rs','input.rs'], 'Q307 verifies four wrong results from this second implementation. The host captures the prior selection and checks same focus, but those guards cannot make character scanning into shaped visual navigation. The fallback ignores layout geometry and modifiers needed for correct line/buffer distinction; PreviousLine/NextLine returns None rather than implementing visual movement.'),
 ('Retained layout capability facades include stubs','OwnedLayout animation queries/ticks return false, scrollbar append emits nothing, and selection_style always returns None.', ['owned_layout.rs','frame.rs'], 'These exact source bodies bound what the wrapper implements. Surrounding frame comments still describe transition ticks and overlay scrollbar geometry. Selection paint always falls back to the fixed translucent blue because style lookup cannot succeed. Supplier paint may implement other behavior, so no complete absence of animation/scrollbars across every render path is claimed without supplier/consumer tracing.'),
 ('Retained geometry and scroll policy are partly repeated','Rootstock delegates layout and common ElementGeometry but separately computes painted rectangles, clips, text offsets and scroll ranges.', ['owned_layout.rs','owned_layout/producer.rs','owned_layout/tests.rs'], 'The live producer-local mapping uses Genet ElementGeometry inverse transforms. painted_rect subtracts viewport/ancestor scroll from raw fragment rectangles; caret APIs separately count text across DOM nodes. Tests read exercise nested/two-axis reveal, scroll clamps, clipped descendants, line overflow and explicit font registration. Transform and transient IME/ghost geometry consistency still needs focused host evidence.'),
 ('Interaction optimization has conservative admission','OwnedLayout tracks the current hover/focus even when no dependent style rule requires a cascade.', ['owned_layout/interaction.rs','owned_layout/interaction/tests.rs','owned_layout/hidden_panel_tests.rs','owned_layout/text_paint_tests.rs'], 'Selector ambiguity such as escapes/comments keeps the full style path. Equal cascade retains generation/scroll/text, while changed styles trigger layout. Source tests cover hidden panel boxes and real paint-slot order under clips/opacity/transforms. Hidden layout tests do not repair toolkit hidden-focus Q298; paint-order assertions are stronger than rectangle-only tests but are not GPU pixels.'),
 ('Presentation preparation is shared while completion tails are repeated','Native surface and installed driver reuse PreparedFrame and WgpuPresentation, but commit/observe/capture/profile/drain tails remain separate.', ['presentation.rs','presentation/frame.rs','presentation/prepare.rs','presentation/drive.rs','presentation/wgpu.rs','presentation/wgpu_driver.rs'], 'Preparation clears the current presentation, checks recovery/lifetime, lays out, stages producers and proposes a checked sequence. Driver completion verifies the exact expected stamp. WgpuDriver owns output/capture lifetime and delegates native or materialized scene rasterization to the same presenter. Recovery/context and core generation need separate owner qualification. No GPU/acquisition/native surface or driver lifecycle was run this pass.'),
 ('Producer purpose migration has an inactive stale constructor','Registry paths pass ProducerFramePurpose, but optional embedding still uses the old frame-info constructor shape.', ['producer.rs','producer/portable.rs','producer/portable_lifecycle_tests.rs','embedding.rs'], 'Q308 binds the exact missing-field compiler diagnostic. Presentation versus export is an actual owner clock distinction: the source test advances only on Presentation and keeps export revision/content generation unchanged. A default feature pass neither compiles nor validates the embedding constructor.'),
 ('Portable capture stages registry changes after admission','PortablePlan validates aggregate source scenes and final envelope before committing retirement/rebind/cache generations.', ['producer/portable.rs','producer/portable_lifecycle_tests.rs','producer/bridge.rs'], 'The producer callbacks run while planning; registry lifecycle/cache changes wait for complete admission. Content generation compares source identity/revision, geometry, scale, encoding/alpha and a bounded digest. Host bridge defers CSS interpretation to resolved layout and supplies timestamps only for the requested draw. Producer callbacks may still change their own clocks before a later admission failure; no rollback/failed-presentation time policy is established by registry staging alone.')
]
entries=[{'id':f'A{782+i}','domain':d,'claim':c,'implementations':['crates/cambium/cambium-rootstock/src/'+n for n in paths],'assessment':a,'state':'current source read with qualified caret/typed-initializer probes','verification':NAME} for i,(d,c,paths,a) in enumerate(rows)]
authority['entries'].extend(entries)
notes.setdefault('review_followups',[]).extend([
 {'verification':NAME,'area':'Retained wrapper stubs and supplier behavior','detail':'OwnedLayout tick/has_active_animations always false; append_scrollbars is empty; selection_style always None. Trace exact supplier paint, declared support and product uses before broad total-feature absence/performance claims. No animation timeline/scrollbar pixels were executed.'},
 {'verification':NAME,'area':'Geometry authority consistency','detail':'Compare public painted_rect/caret point/selection APIs against ElementGeometry and actual transformed/scrolled/IME/ghost paint. Separate raw fragments from viewport/content coordinates; no transformed false-position counterexample run this pass.'},
 {'verification':NAME,'area':'Portable callback time before admission','detail':'Presentation-purpose producer callbacks can advance source time before aggregate/final envelope admission fails. Registry lifecycle staging does not roll back arbitrary callback state. Inspect declared failed-presentation clock semantics before selecting policy or promoting a rollback bug.'}
])
next_read={'path':'crates/cambium/cambium-rootstock/src/producer/portable_tests.rs','start':0,'reason':'Finish producer portable/registry/resource tests, then recovery/scene/tree/window code, native/web hosts and all remaining Mere source.'}
notes['current_area']='Retained layout and presentation source read; producer lifecycle source begun; current host caret and stale embedding constructor verified'
notes['next_area']=next_read['reason']
notes['checkpoint']={'classification':'progress','classification_of_previous_turn':'progress','goal_status':'active; full source incomplete','coverage':stats,'finding_count':len(notes['findings']),'authority_entries':len(authority['entries']),'new_receipts':[NAME,'rootstock_caret_probe_receipt.json','rootstock_embedding_info_v2_probe_receipt.json','rootstock_embedding_info_probe_receipt.json'],'audit_authored_production_edits_this_turn':False,'next_read':next_read,'pending_verification':None,'diagnostic_outcomes':'Eight current Host caret checks pass; exact inactive embedding initializer produces expected E0063. Initial harness E0463 retained; distinct v2 fixes harness dependency loading. No optional-feature graph or GPU/native input run.'}
diff=subprocess.run(['git','diff','--check'],cwd=ROOT,capture_output=True,text=True);assert diff.returncode==0
with (HERE/'rootstock_layout_diff_check.txt').open('x',encoding='utf-8') as f:f.write(diff.stdout+diff.stderr)
evidence=['record_rootstock_layout_review.py','rootstock_layout_diff_check.txt']
for n in ['rootstock_caret_probe','rootstock_embedding_info_probe','rootstock_embedding_info_v2_probe']:
 evidence += [n+'.rs','run_'+n+'.py',n+'_receipt.json',n+'_compile_0.log',n+'_compile_1.log',n+'_compile_2.log']
evidence.append('rootstock_caret_probe_output.log')
addition=f'''

### Retained caret authority, inactive embedding constructor and presentation, 2026-10-17

Eighteen more Rootstock files / 194,499 characters are fully read: multi-host tests, retained OwnedLayout and adjacent geometry/interaction/paint tests, presentation machinery and initial producer/portable lifecycle code. Overall coverage is {stats['complete_files']:,}/{stats['total_files']:,} files and {stats['read_chars']:,}/{stats['total_chars']:,} characters at unchanged HEAD {head}, with no stale hashes or pending chunks. Full-source review remains incomplete.

Q307 verifies a second editor overwriting the correct toolkit result. Rootstock's visual caret correction scans Unicode scalar text rather than shaped lines, uses buffer ends for line motion and collapses from the selection focus. Eight current Host checks compare with/without layout: Home on line two goes to buffer byte 0 instead of line byte 3; End on line one goes to buffer byte 5 instead of line byte 2; Left on selection 1..3 collapses at 2 instead of 1; Right across a combining grapheme snaps back to byte 0 instead of advancing to 3. The no-layout controls preserve the toolkit answer. These are actual Host/model observations, not native injected keys, visual pixels or bidi acceptance.

Q308 verifies a stale optional constructor: embedding::View::frame omits the now-required ProducerFrameInfo::purpose. Its exact current initializer text, against freshly built current Rootstock's public type, produces only E0063 for missing purpose. The default/no-optional-feature toolkit and host build first, explaining why those builds miss it. The initial extraction fixture failed to resolve the fresh Cambium dependency (E0463); the failed receipt is preserved, then a distinct v2 explicitly loads that dependency and obtains the intended missing-field diagnostic. This is a typed initializer check, not a full embedding/egui/Iced feature graph build.

The [layout checkpoint](../../../support/receipts/authority-success-audit/{NAME}) binds the eight successful runtime checks and expected compile refusal over retained exact supplier libraries. Generated fresh rlib/executable/PDB outputs were recorded and removed. A782-A789 track manual-node multi-window tests versus actual portable view custody, competing caret editors, retained wrapper stubs, repeated geometry/scroll policy, interaction/paint test limits, shared presentation preparation versus duplicated completion tails, the producer-purpose migration and staged portable capture. Multi-host's manual moveBefore test does not prove Q301 forest component preservation.

OwnedLayout's animation query/tick return false, its scrollbar append body is empty and selection_style always returns None; surrounding prose still describes richer behavior. These source facts are recorded without claiming every supplier path lacks those features. Producer-local mapping delegates to ElementGeometry, while painted/caret/scroll helpers maintain separate calculations that still need consistency probes. Paint-slot tests inspect real command ordering under clips/opacity/transforms, but were read rather than rerun. Presentation correctly verifies driver stamps, keeps proposed sequence separate from successful commit and shares WgpuPresentation across native/materialized scenes; no GPU/acquisition/recovery acceptance was run.

Portable capture validates aggregate scenes and the final envelope before registry lifecycle/cache changes. Producer callbacks can nevertheless mutate their own clock before a later admission failure; policy remains a named follow-up rather than an invented rollback rule. Production/shared WIP remain byte-preserved, prior audit text is an exact prefix and the index is unchanged. No isolated target, Cargo home or worktree was created. Continue with producer/portable_tests.rs, then remaining producer/recovery/host code and all other unread Mere source.
'''
doc.write_bytes(prefix+addition.encode('utf-8'));save('review_notes.json',notes);save('authority_map.json',authority)
budget=sum(p.stat().st_size for p in HERE.rglob('*') if p.is_file());assert budget<100_000_000
receipt={'date_utc':datetime.now(timezone.utc).isoformat(),'basis_commit':head,'kind':'Retained layout/presentation and initial producer authority review; repository incomplete','prior_receipt':{'path':'rootstock_host_review_receipt.json','sha256':sha(HERE/'rootstock_host_review_receipt.json')},'coverage':stats,'whole_current_files':whole,'source_sha256':{n:sha(ROOT/n) for n in whole},'preserved_production_and_test_hashes':guards,'shared_working_file_sha256':old['shared_working_file_sha256'],'new_findings':['Q307','Q308'],'authority_entries':[e['id'] for e in entries],'audit_authored_production_edits_this_pass':False,'diagnostics':{'rootstock_caret_probe_receipt.json':{'build_exits':[0,0,0],'run_exit':0,'checks':8},'rootstock_embedding_info_v2_probe_receipt.json':{'build_exits':[0,0,1],'run_exit':None,'expected_diagnostic':'E0063 missing purpose','exact_initializer_sha256':hashlib.sha256(expression.encode()).hexdigest()},'rootstock_embedding_info_probe_receipt.json':{'build_exits':[0,0,1],'run_exit':None,'qualification':'failed extraction harness: E0463, not missing-field evidence; superseded by v2'}},'pending_verification':None,'next_read':next_read,'document':{'path':old['document']['path'],'sha256':sha(doc),'preserved_prefix_bytes':len(prefix),'preserved_prefix_sha256':hashlib.sha256(prefix).hexdigest()},'evidence_sha256':{n:sha(HERE/n) for n in evidence},'git_index_sha256':index_hash,'retained_isolation':[],'receipt_budget':{'cap_bytes':100_000_000,'retained_bytes_before_receipt':budget},'limits':'Original current toolkit/Rootstock no optional features over exact retained suppliers. Exact optional initializer type-check only. No whole-current Cargo supplier graph, optional embedding feature graph, native/GPU/persistence/a11y acceptance.'}
save(NAME,receipt)
assert sha(index)==index_hash and doc.read_bytes().startswith(prefix)
assert all(sha(ROOT/n)==h for n,h in {**guards,**receipt['source_sha256']}.items()) and all(sha(HERE/n)==h for n,h in receipt['evidence_sha256'].items())
assert all(sha(ROOT/n)==h for n,h in old['shared_working_file_sha256'].items() if n!=old['document']['path'])
